# Monitoring Stack Environment Variables
# Generated from OpenTofu - do not edit manually

# Grafana admin password
GRAFANA_ADMIN_PASSWORD=${grafana_admin_password}

# Grafana OAuth/OIDC via Authentik
GRAFANA_OAUTH_CLIENT_ID=${grafana_oauth_client_id}
GRAFANA_OAUTH_CLIENT_SECRET=${grafana_oauth_client_secret}
GRAFANA_OAUTH_AUTH_URL=${grafana_oauth_auth_url}
GRAFANA_OAUTH_TOKEN_URL=${grafana_oauth_token_url}
GRAFANA_OAUTH_API_URL=${grafana_oauth_api_url}
GRAFANA_OAUTH_SIGNOUT_URL=${grafana_oauth_signout_url}

# Uptime Kuma credentials (for AutoKuma management)
UPTIME_KUMA_USERNAME=${uptime_kuma_username}
UPTIME_KUMA_PASSWORD=${uptime_kuma_password}

# Discord webhook for notifications
DISCORD_WEBHOOK_URL=${discord_webhook_url}
